// The smoke tests shown in the preview: tiny isolated scenarios (generated by
// gen-smoke.mjs into smoke.json) plus a cheap pass/fail check for each. In a real
// test case these would run BEFORE the expensive stress scenarios; if they don't all
// pass, the stress run is skipped. Here the preview runs each against the reference
// engine and shows the result, previewing that gate.
import smoke from "./smoke.json";
import type { Board, Snapshot } from "../src/app/pages/runs/lattice/renderer";

export interface SmokeTest {
  id: string;
  name: string;
  blurb: string;
  expected: string;
  ticks: number;
  scenario: unknown;
}

export const SMOKE: SmokeTest[] = smoke as SmokeTest[];

export interface CheckResult {
  pass: boolean;
  detail: string;
}

/** Total consumed across every sink, item id → count. */
function sinkTotals(board: Board, snap: Snapshot): Record<string, number> {
  const out: Record<string, number> = {};
  board.entities.forEach((e, i) => {
    const st = snap.entities[i];
    if (e.type === "sink" && st && "sink" in st) {
      for (const [k, v] of Object.entries(st.sink.consumed))
        out[k] = (out[k] ?? 0) + v;
    }
  });
  return out;
}

/** The belt entity's lanes at (x, y), or null. */
function beltAt(board: Board, snap: Snapshot, x: number, y: number) {
  const i = board.entities.findIndex(
    (e) => e.type === "belt" && e.x === x && e.y === y,
  );
  const st = i >= 0 ? snap.entities[i] : undefined;
  return st && "belt" in st ? st.belt : null;
}

/** For each sink, whether it has consumed at least one of every listed item. */
function eachSinkHas(board: Board, snap: Snapshot, items: string[]): boolean[] {
  const res: boolean[] = [];
  board.entities.forEach((e, i) => {
    const st = snap.entities[i];
    if (e.type === "sink" && st && "sink" in st) {
      res.push(items.every((it) => (st.sink.consumed[it] ?? 0) > 0));
    }
  });
  return res;
}

/** The pass/fail check for each smoke test, keyed by its id. */
export const SMOKE_CHECKS: Record<
  string,
  (b: Board, s: Snapshot) => CheckResult
> = {
  "belt-transport": (b, s) => {
    const n = sinkTotals(b, s)["iron-ore"] ?? 0;
    return { pass: n > 0, detail: `sink consumed ${n} iron-ore` };
  },
  "side-load": (b, s) => {
    const belt = beltAt(b, s, 4, 3);
    const top = belt?.left.some((i) => i.item === "iron-ore") ?? false;
    const bottom = belt?.right.some((i) => i.item === "copper-ore") ?? false;
    return {
      pass: top && bottom,
      detail: `top-lane iron: ${top}, bottom-lane copper: ${bottom}`,
    };
  },
  splitter: (b, s) => {
    const oks = eachSinkHas(b, s, ["iron-ore", "iron-plate"]);
    return {
      pass: oks.length === 2 && oks.every(Boolean),
      detail: `each output got both items: [${oks.join(", ")}]`,
    };
  },
  "inserter-belt-belt": (b, s) => {
    const n = sinkTotals(b, s)["iron-ore"] ?? 0;
    return { pass: n > 0, detail: `bottom sink consumed ${n} iron-ore` };
  },
  "assembler-single": (b, s) => {
    const n = sinkTotals(b, s)["iron-plate"] ?? 0;
    return { pass: n > 0, detail: `sink consumed ${n} iron-plate` };
  },
  "assembler-two-input": (b, s) => {
    const n = sinkTotals(b, s)["circuit"] ?? 0;
    return { pass: n > 0, detail: `sink consumed ${n} circuits` };
  },
};
